#include <iostream>
using namespace std;
void insertionSort(int arr[] , int n){
    for(int i = 1;i<=n;i++){
        int curr = arr[i];
        int prev = i-1;

        while(prev >= 0 && arr[prev] > curr){
            arr[prev +  1] = arr[prev];
            prev--;
        }

        arr[prev +  1] = curr;
    }
}
int main()
{
    int n = 5;
    int arr[5] = {4,1,3,2,5};

    insertionSort(arr,n);
    for(int i =0 ;i<n;i++){
        cout<<arr[i]<<" "; 
    }

    return 0;
}

Your insertion sort code has **one small bug** in the loop condition.

### 🧠 Issue:
```cpp
for(int i = 1; i <= n; i++)  // ❌ Incorrect: i should go till n-1
```

Arrays in C++ are 0-indexed, so if `n = 5`, the last index is `4`. Your loop should go from `i = 1` to `i < n`.

---

### ✅ Fix:
```cpp
for(int i = 1; i < n; i++)
```

---

### 🔧 Corrected Code:
```cpp
#include <iostream>
using namespace std;

void insertionSort(int arr[], int n) {
    for(int i = 1; i < n; i++) {
        int curr = arr[i];
        int prev = i - 1;

        while(prev >= 0 && arr[prev] > curr) {
            arr[prev + 1] = arr[prev];
            prev--;
        }
        arr[prev + 1] = curr;
    }
}

int main() {
    int n = 5;
    int arr[5] = {4, 1, 3, 2, 5};

    insertionSort(arr, n);

    for(int i = 0; i < n; i++) {
        cout << arr[i] << " "; 
    }

    return 0;
}
```

---

### 🧪 Output:
```
1 2 3 4 5
```

